    /// will affect any stack trace captured _after_ the value has been changed.
    /// <br /><br />
    /// If set to a non-number value, or set to a negative number, stack traces will
    /// not capture any frames.
    /// </summary>
    abstract stackTraceLimit: float with get, set
    /// <summary>
    /// Thrown when no credentials found in environment
    /// </summary>
    [<EmitConstructor>]
    abstract Create: message: string -> MissingCredentialsError

/// <summary>
/// Thrown when bucket name, mount path, or options are invalid
/// </summary>
type InvalidMountConfigErrorConstructor =
    /// <summary>
    /// Indicates whether the argument provided is a built-in Error instance or not.
    /// </summary>
    abstract isError: error: obj -> bool
    /// <summary>
    /// Creates a <c>.stack</c> property on <c>targetObject</c>, which when accessed returns
    /// a string representing the location in the code at which
    /// <c>Error.captureStackTrace()</c> was called.
    /// <code lang="js">
    /// const myObject = {};
    /// Error.captureStackTrace(myObject);
    /// myObject.stack;  // Similar to `new Error().stack`
    /// </code>
    /// <br /><br />
    /// The first line of the trace will be prefixed with
    /// <c>${myObject.name}: ${myObject.message}</c>.
    /// <br /><br />
    /// The optional <c>constructorOpt</c> argument accepts a function. If given, all frames
    /// above <c>constructorOpt</c>, including <c>constructorOpt</c>, will be omitted from the
    /// generated stack trace.
    /// <br /><br />
    /// The <c>constructorOpt</c> argument is useful for hiding implementation
    /// details of error generation from the user. For instance:
    /// <code lang="js">
    /// function a() {
    ///   b();
    /// }
    ///
    /// function b() {
    ///   c();
    /// }
    ///
    /// function c() {
    ///   // Create an error without stack trace to avoid calculating the stack trace twice.
    ///   const { stackTraceLimit } = Error;
    ///   Error.stackTraceLimit = 0;
    ///   const error = new Error();
    ///   Error.stackTraceLimit = stackTraceLimit;
    ///
    ///   // Capture the stack trace above function b
    ///   Error.captureStackTrace(error, b); // Neither function c, nor b is included in the stack trace
    ///   throw error;
    /// }
    ///
    /// a();
    /// </code>
    /// </summary>
    abstract captureStackTrace: targetObject: obj * ?constructorOpt: JS.Function -> unit
    /// <remarks>@see https://v8.dev/docs/stack-trace-api#customizing-stack-traces</remarks>
    abstract prepareStackTrace: err: exn * stackTraces: obj[] -> obj
    /// <summary>
    /// The <c>Error.stackTraceLimit</c> property specifies the number of stack frames
    /// collected by a stack trace (whether generated by <c>new Error().stack</c> or
    /// <c>Error.captureStackTrace(obj)</c>).
    /// <br /><br />
    /// The default value is <c>10</c> but may be set to any valid JavaScript number. Changes
    /// will affect any stack trace captured _after_ the value has been changed.
    /// <br /><br />
    /// If set to a non-number value, or set to a negative number, stack traces will
    /// not capture any frames.
    /// </summary>
    abstract stackTraceLimit: float with get, set
    /// <summary>
    /// Thrown when bucket name, mount path, or options are invalid
    /// </summary>
    [<EmitConstructor>]
    abstract Create: message: string -> InvalidMountConfigError

/// <summary>
/// Client for Git repository operations
/// </summary>
type GitClientConstructor =
    abstract REQUEST_TIMEOUT_BUFFER_MS: obj
    /// <summary>
    /// Client for Git repository operations
    /// </summary>
    [<EmitConstructor>]
    abstract Create: ?options: SandboxClientOptions -> GitClient

type SandboxConstructor =
    /// <summary>
    /// UUID v4 format validator for backup IDs
    /// </summary>
    abstract UUID_REGEX: obj
    /// <summary>
    /// Validate that a directory path is safe for backup operations.
    /// Rejects empty, relative, traversal, null-byte, and unsupported-root paths.
    /// </summary>
    abstract validateBackupDir: obj with get, set
    abstract PRESIGNED_URL_EXPIRY_SECONDS: obj
    abstract outboundByHost: Record<string, Func<obj, obj, Sandbox.OutboundByHost.Item.Ctx<obj>, obj>> option with get, set
    abstract outboundHandlers: Record<string, Func<obj, obj, Sandbox.OutboundByHost.Item.Ctx<obj>, obj>> option with get, set
    abstract outbound: Func<obj, obj, Sandbox.OutboundByHost.Item.Ctx<obj>, obj> option with get, set
    abstract outboundProxies: Record<string, Func<obj, obj, Sandbox.OutboundByHost.Item.Ctx<obj>, obj>> option with get, set
    abstract outboundProxy: Func<obj, obj, Sandbox.OutboundByHost.Item.Ctx<obj>, obj> option with get, set
    [<EmitConstructor>]
    abstract Create<'Env>: ctx: obj * env: 'Env -> Sandbox<'Env>
